-- Run ENTIRE file in MySQL Workbench (File -> Open SQL Script -> Execute).
-- Application 406: Purchase Order Report - Local.pdf
-- Expected base64 length: 80736

USE velocity;
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- max_allowed_packet is GLOBAL-only on many servers (Error 1621 if you SET SESSION).
-- ~80 KB base64 is fine if global max_allowed_packet >= 4M (default is often 64M).
SELECT @@global.max_allowed_packet AS global_max_allowed_packet,
       @@session.max_allowed_packet AS session_max_allowed_packet;

START TRANSACTION;

SET @app_id = 406;
SET @file_name = 'Purchase Order Report - Local.pdf';
SET @mime_type = 'application/pdf';
SET @b64_part_0 = '';
SET @b64_part_1 = '';
SET @b64_part_2 = '';
SET @b64_part_3 = '';
SET @b64_part_4 = '';
SET @b64_part_5 = '';
SET @b64_part_6 = '';
SET @b64 = CONCAT(@b64_part_0, @b64_part_1, @b64_part_2, @b64_part_3, @b64_part_4, @b64_part_5, @b64_part_6);

SELECT LENGTH(@b64) AS b64_chars_loaded,
       CASE WHEN LENGTH(@b64) >= 80636 THEN 'OK' ELSE 'ERROR - b64 truncated' END AS b64_check;

SET @data_json = (
    SELECT
        CASE
            WHEN a.txt_application_data IS NULL THEN CAST('{}' AS JSON)
            WHEN JSON_TYPE(a.txt_application_data) = 'STRING' THEN CAST(JSON_UNQUOTE(a.txt_application_data) AS JSON)
            ELSE a.txt_application_data
        END
    FROM cfg_tbl_custom_form_application a
    WHERE a.ser_application_id = @app_id
);

-- PS-0016 / app 406 — attachment field from diagnose (do not guess another key)
SET @field_id = 'field-1789019525113-fc29d9bcc9e69';

SELECT @field_id AS attachment_field_id,
       CASE WHEN @field_id IS NULL THEN 'ERROR - no attachment field' ELSE 'OK' END AS field_lookup;

SET @root_path = CONCAT('$.', JSON_QUOTE(@field_id));
SET @tv_path = CONCAT('$.templateValues.', JSON_QUOTE(@field_id));
SET @tv_b64_path = CONCAT(@tv_path, '[0].base64');

-- Workbench + large vars: JSON_OBJECT('base64', @b64) often stores empty base64 even when LENGTH(@b64)=80736.
-- Build the array as text, then CAST to JSON (base64 is quote-safe: A-Za-z0-9+/=).
SET @payload_text = CONCAT(
    '[{"fileName":"',
    REPLACE(REPLACE(@file_name, '\\', '\\\\'), '"', '\\"'),
    '","mimeType":"',
    REPLACE(REPLACE(@mime_type, '\\', '\\\\'), '"', '\\"'),
    '","base64":"',
    @b64,
    '"}]'
);
SET @payload = CAST(@payload_text AS JSON);

-- Patch only the attachment slot + root mirror (avoid holding a full merged doc in @data_after).
SET @patch_text = CONCAT(
    '{',
    '"templateValues":{',
    JSON_QUOTE(@field_id),
    ':',
    @payload_text,
    '},',
    JSON_QUOTE(@field_id),
    ':',
    @payload_text,
    '}'
);
SET @patch = CAST(@patch_text AS JSON);

SELECT
    LENGTH(@b64) AS session_b64_len,
    CHAR_LENGTH(@payload_text) AS payload_text_chars,
    CHAR_LENGTH(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(@payload, '$[0].base64')), '')) AS payload_b64_len,
    CHAR_LENGTH(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(@patch, CONCAT('$.templateValues.', JSON_QUOTE(@field_id), '[0].base64'))), '')) AS patch_tv_b64_len,
    CASE
        WHEN CHAR_LENGTH(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(@payload, '$[0].base64')), '')) >= 80636 THEN 'OK - payload ready'
        ELSE 'ERROR - payload missing base64'
    END AS payload_check;

-- Workbench often shows staged_tv_base64_len=0 on @data_after even when the server can persist the row.
-- Apply on the column in-place; trust payload_b64_len for the guard, verify from the table after UPDATE.
UPDATE cfg_tbl_custom_form_application a
SET
    a.txt_application_data = JSON_MERGE_PATCH(
        CASE
            WHEN a.txt_application_data IS NULL THEN CAST('{}' AS JSON)
            WHEN JSON_TYPE(a.txt_application_data) = 'STRING' THEN CAST(JSON_UNQUOTE(a.txt_application_data) AS JSON)
            ELSE a.txt_application_data
        END,
        @patch
    ),
    a.dte_modified_date = NOW(),
    a.ser_modified_user = 1
WHERE a.ser_application_id = @app_id
  AND @field_id IS NOT NULL
  AND LENGTH(@b64) > 1000
  AND CHAR_LENGTH(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(@payload, '$[0].base64')), '')) >= 80636;

SELECT
    @app_id AS application_id,
    @file_name AS file_name,
    ROW_COUNT() AS rows_updated,
    (
        SELECT MAX(CHAR_LENGTH(COALESCE(x.b64, '')))
        FROM JSON_TABLE(
            COALESCE(
                JSON_EXTRACT(a.txt_application_data, @tv_path),
                JSON_EXTRACT(a.txt_application_data, @root_path),
                JSON_ARRAY()
            ),
            '$[*]' COLUMNS (b64 LONGTEXT PATH '$.base64')
        ) x
    ) AS max_base64_chars_in_db,
    CASE
        WHEN (
            SELECT MAX(CHAR_LENGTH(COALESCE(x.b64, '')))
            FROM JSON_TABLE(
                COALESCE(
                    JSON_EXTRACT(a.txt_application_data, @tv_path),
                    JSON_EXTRACT(a.txt_application_data, @root_path),
                    JSON_ARRAY()
                ),
                '$[*]' COLUMNS (b64 LONGTEXT PATH '$.base64')
            ) x
        ) >= 80636 THEN 'OK - OPENABLE'
        WHEN ROW_COUNT() = 0 THEN 'ERROR - no UPDATE (payload check failed?)'
        ELSE 'ERROR - DB still missing base64; run import_application_attachment.ps1 via mysql CLI'
    END AS import_result
FROM cfg_tbl_custom_form_application a
WHERE a.ser_application_id = @app_id;

COMMIT;
